style.css:
/* Strawberry Milk — edufr ISA Web */

:root {
  /* swap these colors if you want */
  --my-pink: #e88caf;
  --my-light-pink: #fff0f5;
  --my-dark-pink: #bd6489;
  --my-text: #634958;
  --my-white: #fffafd;
}

/* soft pink page background */
html,
body {
  background: var(--my-light-pink) !important;
  color: var(--my-text) !important;
  font-family: "Trebuchet MS", sans-serif !important;
}

/* prettier links */
a {
  color: var(--my-dark-pink) !important;
  text-decoration: none !important;
}

a:hover {
  color: var(--my-pink) !important;
  text-decoration: underline !important;
}

/* softer form fields */
input,
select,
textarea {
  background: var(--my-white) !important;
  color: var(--my-text) !important;
  border: 1px solid #f0bfd1 !important;
  border-radius: 10px !important;
  padding: 7px !important;
}

/* pink buttons */
button,
input[type="button"],
input[type="submit"] {
  background: var(--my-pink) !important;
  color: white !important;
  border: none !important;
  border-radius: 12px !important;
  padding: 8px 16px !important;
  cursor: pointer !important;
}

/* gentle hover effect */
button:hover,
input[type="button"]:hover,
input[type="submit"]:hover {
  background: var(--my-dark-pink) !important;
}

/* softer tables */
table {
  border-color: #f2c9d9 !important;
}

th {
  background: #f8d6e3 !important;
  color: #75445d !important;
}

td {
  border-color: #f5dce6 !important;
}

/* cute selection color */
::selection {
  background: #f5bfd4 !important;
  color: #634958 !important;
}
